from pathlib import Path
import re,json
s=Path('planning/plan.md').read_text()
spec=Path('planning/spec.md').read_text()
assert re.findall(r'^## (.+)$',s,re.M)==['Choices','Steps','Test plan','Coverage']
cases={}
for line in s.splitlines():
    if re.match(r'^\| T-\d+ / step',line):
        cells=line.split('|');assert len(cells)==8
        n,step=map(int,re.search(r'T-(\d+) / step (\d+)',cells[1]).groups())
        assert n not in cases
        cases[n]=(step,{int(i) for i in re.findall(r'R-(\d+)',cells[6])})
assert set(cases)==set(range(1,44))
reqs={int(m.group(1)):m.group(2).strip() for m in re.finditer(r'^\| R-(\d+) \| ([^|]+) \|',spec,re.M)}
coverage={}
for m in re.finditer(r'^\| R-(\d+) \| ([^|]+) \| ([^|]+) \| ([^|]+) \|$',s,re.M):
    i=int(m.group(1));assert i not in coverage
    assert m.group(2).strip()==reqs[i]
    ns={int(n) for n in re.findall(r'T-(\d+)',m.group(4))}
    assert ns and all(i in cases[n][1] for n in ns)
    assert ns=={n for n,(_,refs) in cases.items() if i in refs}
    assert {int(x) for x in m.group(3).split(',')}=={cases[n][0] for n in ns}
    coverage[i]=ns
assert set(coverage)==set(range(1,96))
assert all(line==line.rstrip() for line in s.splitlines())
assert '|---|---|---|---|\n\n| R-' not in s
# Check scalar expectations against original decoded messages.
for line in s.splitlines():
    if line.startswith('| materials/requests/'):
        cells=line.split('|');p=re.search(r'materials/requests/IT-\d+\.json',cells[1]).group()
        msg=json.loads(Path(p).read_text())['message']
        vals=json.loads(cells[2].strip().strip('`'));assert len(vals)==11
        for i,v in enumerate(vals):
            if v is not None and i!=1:assert v in msg,(p,v)
print('PASS: 95/95 traceability rows exactly match spec requirements and owning test-case references.')
print('PASS: 43 case groups each assigned once across 7 steps; coverage table is valid contiguous Markdown.')
print('PASS: expected scalar facts still match original source messages; no runtime test coverage implied.')
print('Required verification groups: complete=T02, missing dates=T03, conflicts=T04, instructions=T05, provider failure=T31, unchanged=T21, changed=T22, paraphrase=T14, refusal=T18, interrupted=T19, failed retry=T25.')
