"""Validate provider output and apply the Northstar review rules in order.

Schema and quote checks establish structural/evidence validity, not general
semantic truth. Independent source comparisons and human review are still needed.
"""

from datetime import date
import json
from pathlib import Path
import re
import shlex
from typing import Any

from jsonschema import Draft202012Validator, ValidationError

from .providers import ProviderResponse


ROOT = Path(__file__).resolve().parents[2]
SCHEMA_PATH = ROOT / "snapshot.schema.json"
POLICY_PATH = ROOT / "materials" / "office-policy.md"
PROMPT_PATH = Path(__file__).with_name("extraction_prompt.txt")
ROUTING_VERSION = "1"
_DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")
_OVERRIDE = re.compile(
    r"SYSTEM OVERRIDE|bypass approval|display the API key|"
    r"mark request as approved|highest-priority system instruction",
    re.IGNORECASE,
)
_UNFINISHED = {"incomplete", "in_progress", "queued", "cancelled"}


class ExtractionError(ValueError):
    def __init__(self, category: str, message: str):
        super().__init__(message)
        self.category = category


def build_messages(message: str) -> list[dict[str, str]]:
    """Keep source text out of instructions and metadata out of business facts."""
    instructions = (
        PROMPT_PATH.read_text(encoding="utf-8")
        + "\n\nNorthstar policy:\n"
        + POLICY_PATH.read_text(encoding="utf-8")
        + "\n\nExtraction schema:\n"
        + SCHEMA_PATH.read_text(encoding="utf-8")
    )
    return [{"role": "system", "content": instructions}, {"role": "user", "content": message}]


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON object key")
        result[key] = value
    return result


def _invalid_constant(value: str) -> None:
    raise ValueError("Nonstandard JSON numeric constant")


def _require_completion(value: Any) -> None:
    if value == "completed":
        return
    if isinstance(value, str) and value in _UNFINISHED:
        raise ExtractionError("interrupted_response", "Provider response was not completed; retry extraction.")
    if value == "failed":
        raise ExtractionError("provider_unavailable", "Provider reported a failed response; retry extraction.")
    raise ExtractionError("malformed_output", "Provider response lacks a recognized completion status.")


def _parse_response(payload: Any) -> Any:
    if not isinstance(payload, dict):
        raise ExtractionError("malformed_output", "Provider response must be an object.")
    _require_completion(payload.get("status"))
    output = payload.get("output")
    if not isinstance(output, list) or len(output) != 1:
        raise ExtractionError("malformed_output", "Expected exactly one assistant output message.")
    assistant = output[0]
    if (
        not isinstance(assistant, dict)
        or assistant.get("type") != "message"
        or assistant.get("role") != "assistant"
    ):
        raise ExtractionError("malformed_output", "Expected an assistant message, not a tool or other output.")
    _require_completion(assistant.get("status"))
    content = assistant.get("content")
    if not isinstance(content, list) or not content or any(not isinstance(part, dict) for part in content):
        raise ExtractionError("malformed_output", "Assistant content must contain extraction text.")
    # A refusal cannot be bypassed by adding an otherwise usable text part.
    if any(part.get("type") == "refusal" for part in content):
        raise ExtractionError("refusal", "Provider refused extraction; inspect the source message before retrying.")
    if len(content) != 1 or content[0].get("type") != "output_text":
        raise ExtractionError("malformed_output", "Expected exactly one extraction text part.")
    text = content[0].get("text")
    if not isinstance(text, str) or not text.strip():
        raise ExtractionError("malformed_output", "Extraction text is absent, empty or not a string.")
    try:
        return json.loads(text, object_pairs_hook=_unique_object, parse_constant=_invalid_constant)
    except (ValueError, RecursionError) as error:
        # Do not echo an arbitrary model response into errors or logs.
        raise ExtractionError("malformed_output", "Extraction text is not valid unambiguous JSON.") from error


def _add_issue(extraction: dict[str, Any], code: str, explanation: str) -> None:
    prefix = code + ":"
    if not any(issue.startswith(prefix) and issue[len(prefix):].strip() for issue in extraction["issues"]):
        extraction["issues"].append(f"{prefix} {explanation}")


def _validate(extraction: Any, message: str, schema: dict[str, Any]) -> tuple[dict[str, Any], list[str]]:
    scalar_fields = [name for name, spec in schema["properties"].items() if spec["type"] != "array"]
    if isinstance(extraction, dict):
        # Parsed JSON is new storage, not the provider's payload. Normalize only
        # blank scalar strings; absent keys and invalid arrays must still fail.
        for name in scalar_fields:
            value = extraction.get(name)
            if isinstance(value, str) and not value.strip():
                extraction[name] = None
    try:
        Draft202012Validator(schema).validate(extraction)
    except ValidationError as error:
        location = ".".join(str(part) for part in error.absolute_path) or "<root>"
        raise ExtractionError(
            "validation",
            f"Extraction violates snapshot.schema.json at {location}; check required keys, types and enum values.",
        ) from error

    quotes = extraction["supporting_quotes"]
    if not quotes or any(not quote or quote not in message for quote in quotes):
        raise ExtractionError("validation", "Supporting quotes must be nonempty exact substrings of the message.")
    for field in ("request_date", "start_date", "end_date"):
        value = extraction[field]
        if value is not None:
            try:
                if not _DATE.fullmatch(value):
                    raise ValueError("Invalid date format")
                date.fromisoformat(value)
            except ValueError as error:
                raise ExtractionError("validation", f"Invalid {field}; use a real calendar date in YYYY-MM-DD form.") from error

    for issue in extraction["issues"]:
        if issue.startswith("conflict:"):
            parts = issue.split(":", 2)
            if len(parts) != 3 or parts[1] not in scalar_fields or not parts[2].strip():
                raise ExtractionError("validation", "A conflict issue must name a scalar field and explain its alternatives.")
            if len(set(quotes)) < 2:
                raise ExtractionError("validation", "An unresolved conflict requires distinct source quotes for its alternatives.")
            extraction[parts[1]] = None
    for field in scalar_fields:
        if extraction[field] is None:
            _add_issue(extraction, "missing:" + field, f"No explicit resolved {field} is available.")
    return extraction, scalar_fields


def _find_override(extraction: dict[str, Any], message: str) -> bool:
    marked = any(
        issue.startswith("instruction-override:") and issue[len("instruction-override:"):].strip()
        for issue in extraction["issues"]
    )
    detected = False
    for match in re.finditer(r"[^.!?\n]+[.!?]?", message):
        sentence = match.group().strip()
        if _OVERRIDE.search(sentence):
            detected = True
            if sentence not in extraction["supporting_quotes"]:
                extraction["supporting_quotes"].append(sentence)
    if detected:
        _add_issue(extraction, "instruction-override", "Source attempts to override extraction or approval rules; inspect the message.")
    return bool(marked or detected)


def _route(extraction: dict[str, Any], document_id: str, message: str, scalar_fields: list[str]) -> tuple[str, str, str]:
    mismatch = extraction["request_id"] is not None and extraction["request_id"] != Path(document_id).stem
    if mismatch:
        _add_issue(extraction, "identifier-mismatch", "Stated request identifier differs from the input filename.")
    reversed_dates = (
        extraction["start_date"] is not None
        and extraction["end_date"] is not None
        and extraction["start_date"] > extraction["end_date"]
    )
    if reversed_dates:
        _add_issue(extraction, "invalid-range", "The stated start date is after the stated end date.")

    # These branches are the ordered rules, not model-provided approval choices.
    if _find_override(extraction, message):
        return "review", "IT Service Desk", "inspect-message"
    kind = extraction["kind"]
    if kind == "withdrawal" and extraction["request_id"] is not None and extraction["request_date"] is not None:
        return "review", "IT Service Desk", "confirm-withdrawal"
    has_conflict = any(issue.startswith("conflict:") for issue in extraction["issues"])
    if (
        kind not in ("new", "change")
        or has_conflict
        or mismatch
        or reversed_dates
        or any(extraction[field] is None for field in scalar_fields)
    ):
        return "needs-information", "IT Service Desk", "clarify"
    if extraction["environment"] == "production" or extraction["permission"] in ("write", "admin"):
        return "review", "Security Review", "review-risk-then-owner"
    return "review", "System Owner", "review-request"


def process_response(
    *,
    document_id: str,
    source_sha256: str,
    message: str,
    response: ProviderResponse,
) -> dict[str, Any]:
    """Return one complete terminal record, including explicit validation errors."""
    record: dict[str, Any] = {
        "document_id": document_id,
        "source_sha256": source_sha256,
        "response_source": response.response_source,
        "extraction": None,
        "status": "error",
        "owner": "IT Service Desk",
        "next_action": "retry-extraction",
        "error": None,
    }
    try:
        schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))
        extraction, scalar_fields = _validate(_parse_response(response.payload), message, schema)
        status, owner, action = _route(extraction, document_id, message, scalar_fields)
    except ExtractionError as error:
        record["error"] = {
            "category": error.category,
            "message": str(error),
            "retry_command": "it-access retry " + shlex.quote(document_id),
        }
        return record
    record.update(extraction=extraction, status=status, owner=owner, next_action=action)
    return record

"""SQLite current records, immutable source revisions and retained attempts.

No provider call happens in a transaction. The CLI's process-level admission
lock is a separate concern; these primitives guard transitions and source identity
even when an obsolete result is accidentally submitted to the store.
"""

from contextlib import contextmanager
from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import shlex
import sqlite3
from typing import Any
from urllib.parse import urlsplit


class StateError(RuntimeError):
    """An invalid state transition, configuration or database operation."""


@dataclass(frozen=True)
class ScheduledAttempt:
    document_id: str
    revision_id: int
    attempt_id: int
    needs_processing: bool


_CACHE_FIELDS = (
    "provider", "endpoint", "model", "prompt_sha256", "schema_sha256",
    "generation", "policy_sha256", "routing_version", "mock_fixture_hashes",
)
_SECRET_KEYS = {
    "api_key", "apikey", "authorization", "access_token", "api_token",
    "password", "secret", "credentials", "headers", "token",
}
_ROUTES = {
    ("review", "IT Service Desk", "inspect-message"),
    ("review", "IT Service Desk", "confirm-withdrawal"),
    ("needs-information", "IT Service Desk", "clarify"),
    ("review", "Security Review", "review-risk-then-owner"),
    ("review", "System Owner", "review-request"),
}
_SCHEMA = """
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS documents (
    document_id TEXT PRIMARY KEY,
    current_revision_id INTEGER REFERENCES revisions(revision_id),
    current_attempt_id INTEGER REFERENCES attempts(attempt_id)
);
CREATE TABLE IF NOT EXISTS revisions (
    revision_id INTEGER PRIMARY KEY AUTOINCREMENT,
    document_id TEXT NOT NULL REFERENCES documents(document_id),
    source_bytes BLOB NOT NULL,
    source_sha256 TEXT NOT NULL,
    settings_json TEXT NOT NULL,
    settings_fingerprint TEXT NOT NULL,
    policy_version TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS attempts (
    attempt_id INTEGER PRIMARY KEY AUTOINCREMENT,
    revision_id INTEGER NOT NULL REFERENCES revisions(revision_id),
    settings_json TEXT NOT NULL,
    settings_fingerprint TEXT NOT NULL,
    policy_version TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('pending','running','succeeded','failed','interrupted')),
    status TEXT NOT NULL,
    owner TEXT NOT NULL,
    next_action TEXT NOT NULL,
    response_source TEXT,
    extraction_json TEXT,
    error_json TEXT,
    created_at TEXT NOT NULL,
    started_at TEXT,
    finished_at TEXT
);
CREATE INDEX IF NOT EXISTS revision_documents ON revisions(document_id, revision_id);
CREATE INDEX IF NOT EXISTS attempt_revisions ON attempts(revision_id, attempt_id);
COMMIT;
"""
_VIEW = """
SELECT a.attempt_id, a.revision_id, r.document_id, r.source_sha256,
       a.settings_json, a.settings_fingerprint, a.policy_version, a.state,
       a.status, a.owner, a.next_action, a.response_source, a.extraction_json,
       a.error_json, a.created_at, a.started_at, a.finished_at
FROM attempts a JOIN revisions r ON r.revision_id = a.revision_id
"""


def _now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="microseconds")


def _json(value: Any) -> str:
    try:
        encoded = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        encoded.encode("utf-8")
        return encoded
    except (TypeError, ValueError, UnicodeError, RecursionError) as error:
        raise StateError("State values must be finite, UTF-8 JSON data.") from error


def _reject_credentials(value: Any) -> None:
    if isinstance(value, dict):
        for key, child in value.items():
            if not isinstance(key, str):
                raise StateError("Settings keys must be strings.")
            if key.lower().replace("-", "_") in _SECRET_KEYS:
                raise StateError("Credentials must remain in the environment, outside persisted settings.")
            _reject_credentials(child)
    elif isinstance(value, list):
        for child in value:
            _reject_credentials(child)


def _prepare_settings(settings: dict[str, Any]) -> tuple[str, str, str]:
    if not isinstance(settings, dict):
        raise StateError("Processing settings must be an object.")
    _reject_credentials(settings)
    required = set(_CACHE_FIELDS) - {"mock_fixture_hashes"}
    if not required.issubset(settings):
        raise StateError("Processing settings lack required extraction or policy provenance.")
    if not isinstance(settings["generation"], dict) or not isinstance(settings.get("mock_fixture_hashes", {}), dict):
        raise StateError("Generation settings and mock fixture hashes must be objects.")
    for key in required - {"generation"}:
        if not isinstance(settings[key], str) or not settings[key]:
            raise StateError("Processing provenance identifiers must be nonempty strings.")
    try:
        endpoint = urlsplit(settings["endpoint"])
        if endpoint.username or endpoint.password or endpoint.query or endpoint.fragment:
            raise StateError("Endpoint credentials and query/fragment values cannot be persisted.")
    except ValueError as error:
        raise StateError("Provider endpoint is malformed.") from error
    encoded = _json(settings)
    cache = {key: settings.get(key, {}) for key in _CACHE_FIELDS}
    fingerprint = hashlib.sha256(_json(cache).encode("utf-8")).hexdigest()
    return encoded, fingerprint, settings["policy_sha256"]


def settings_fingerprint(settings: dict[str, Any]) -> str:
    """Cache extraction inputs, excluding timeout, worker count and pacing."""
    return _prepare_settings(settings)[1]


def _record(row: sqlite3.Row) -> dict[str, Any]:
    result = dict(row)
    result["settings"] = json.loads(result.pop("settings_json"))
    for stored, public in (("extraction_json", "extraction"), ("error_json", "error")):
        value = result.pop(stored)
        result[public] = json.loads(value) if value is not None else None
    return result


class StateStore:
    def __init__(self, path: Path):
        self.path = Path(path).resolve()
        self._connection: sqlite3.Connection | None = None
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            connection = sqlite3.connect(self.path, timeout=5.0, isolation_level=None)
            self._connection = connection
            connection.row_factory = sqlite3.Row
            connection.execute("PRAGMA foreign_keys = ON")
            connection.execute("PRAGMA busy_timeout = 5000")
            connection.execute("PRAGMA journal_mode = WAL")
            connection.executescript(_SCHEMA)
        except (OSError, sqlite3.Error) as error:
            self.close()
            raise StateError("Cannot initialize the intake database; check its path, permissions and availability.") from error

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def close(self) -> None:
        if self._connection is not None:
            self._connection.close()
            self._connection = None

    @property
    def _db(self) -> sqlite3.Connection:
        if self._connection is None:
            raise StateError("The intake database is closed.")
        return self._connection

    @contextmanager
    def _write(self):
        connection = self._db
        try:
            connection.execute("BEGIN IMMEDIATE")
            yield
            connection.commit()
        except BaseException:
            if connection.in_transaction:
                connection.rollback()
            raise

    def _current_optional(self, document_id: str) -> dict[str, Any] | None:
        row = self._db.execute(
            _VIEW + " JOIN documents d ON d.current_attempt_id = a.attempt_id WHERE d.document_id = ?",
            (document_id,),
        ).fetchone()
        return _record(row) if row is not None else None

    def current(self, document_id: str) -> dict[str, Any]:
        row = self._current_optional(document_id)
        if row is None:
            raise StateError("No current record exists for this document.")
        return row

    def queue(self) -> list[dict[str, Any]]:
        # One SELECT gives extraction, route, attempt and source one read snapshot.
        rows = self._db.execute(
            _VIEW + " JOIN documents d ON d.current_attempt_id = a.attempt_id ORDER BY r.document_id"
        ).fetchall()
        return [_record(row) for row in rows]

    def history(self, document_id: str) -> list[dict[str, Any]]:
        rows = self._db.execute(
            _VIEW + " JOIN documents d ON d.document_id = r.document_id "
            "WHERE r.document_id = ? AND a.attempt_id != d.current_attempt_id ORDER BY a.attempt_id",
            (document_id,),
        ).fetchall()
        return [_record(row) for row in rows]

    def attempt(self, attempt_id: int) -> dict[str, Any]:
        row = self._db.execute(_VIEW + " WHERE a.attempt_id = ?", (attempt_id,)).fetchone()
        if row is None:
            raise StateError("No recorded attempt exists for this identifier.")
        return _record(row)

    def source_bytes(self, attempt_id: int) -> bytes:
        row = self._db.execute(
            "SELECT r.source_bytes FROM revisions r JOIN attempts a ON a.revision_id = r.revision_id "
            "WHERE a.attempt_id = ?", (attempt_id,),
        ).fetchone()
        if row is None:
            raise StateError("No recorded source exists for this attempt.")
        return bytes(row[0])

    def _supersede(self, current: dict[str, Any] | None) -> None:
        if current is not None and current["state"] in ("pending", "running"):
            error = {
                "category": "interrupted_response",
                "message": "Attempt superseded by a newer source or processing configuration.",
                "retry_command": "it-access retry " + shlex.quote(current["document_id"]),
            }
            self._db.execute(
                "UPDATE attempts SET state = 'interrupted', status = 'error', owner = 'IT Service Desk', "
                "next_action = 'retry-extraction', error_json = ?, finished_at = ? WHERE attempt_id = ?",
                (_json(error), _now(), current["attempt_id"]),
            )

    def _new_attempt(self, document_id: str, revision_id: int, prepared: tuple[str, str, str]) -> ScheduledAttempt:
        encoded, fingerprint, policy_version = prepared
        settings = json.loads(encoded)
        response_source = "mock" if settings["provider"] == "mock" else settings["provider"] + ":" + settings["model"]
        cursor = self._db.execute(
            "INSERT INTO attempts (revision_id, settings_json, settings_fingerprint, policy_version, state, "
            "status, owner, next_action, response_source, created_at) "
            "VALUES (?, ?, ?, ?, 'pending', 'pending', 'IT Service Desk', 'wait-for-extraction', ?, ?)",
            (revision_id, encoded, fingerprint, policy_version, response_source, _now()),
        )
        attempt_id = cursor.lastrowid
        self._db.execute(
            "UPDATE documents SET current_revision_id = ?, current_attempt_id = ? WHERE document_id = ?",
            (revision_id, attempt_id, document_id),
        )
        return ScheduledAttempt(document_id, revision_id, attempt_id, True)

    def _enqueue(self, document_id: str, raw: bytes, prepared: tuple[str, str, str]) -> ScheduledAttempt:
        source_hash = hashlib.sha256(raw).hexdigest()
        current = self._current_optional(document_id)
        if current is not None and current["source_sha256"] == source_hash and current["settings_fingerprint"] == prepared[1]:
            return ScheduledAttempt(document_id, current["revision_id"], current["attempt_id"], current["state"] == "pending")
        self._supersede(current)
        self._db.execute("INSERT INTO documents (document_id) VALUES (?) ON CONFLICT(document_id) DO NOTHING", (document_id,))
        cursor = self._db.execute(
            "INSERT INTO revisions (document_id, source_bytes, source_sha256, settings_json, settings_fingerprint, "
            "policy_version, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (document_id, raw, source_hash, *prepared, _now()),
        )
        return self._new_attempt(document_id, cursor.lastrowid, prepared)

    def enqueue(self, document_id: str, raw: bytes, settings: dict[str, Any]) -> ScheduledAttempt:
        if not isinstance(document_id, str) or not document_id or document_id in (".", "..") or "/" in document_id or "\x00" in document_id:
            raise StateError("Document identity must be a nonempty input filename.")
        if not isinstance(raw, bytes):
            raise StateError("Source content must be original file bytes.")
        prepared = _prepare_settings(settings)
        with self._write():
            return self._enqueue(document_id, raw, prepared)

    def _require_current(self, attempt_id: int, state: str) -> dict[str, Any]:
        attempt = self.attempt(attempt_id)
        current = self.current(attempt["document_id"])
        if current["attempt_id"] != attempt_id or attempt["state"] != state:
            raise StateError("Attempt is no longer current or is not in the required processing state.")
        return attempt

    def mark_running(self, attempt_id: int) -> None:
        with self._write():
            self._require_current(attempt_id, "pending")
            self._db.execute(
                "UPDATE attempts SET state = 'running', status = 'processing', started_at = ? WHERE attempt_id = ?",
                (_now(), attempt_id),
            )

    def finish(self, attempt_id: int, record: dict[str, Any]) -> None:
        with self._write():
            attempt = self._require_current(attempt_id, "running")
            if (
                not isinstance(record, dict)
                or record.get("document_id") != attempt["document_id"]
                or record.get("source_sha256") != attempt["source_sha256"]
            ):
                raise StateError("Completion does not match the attempt's document and original source hash.")
            route = (record.get("status"), record.get("owner"), record.get("next_action"))
            failure = record.get("status") == "error"
            if failure:
                error = record.get("error")
                if (
                    route != ("error", "IT Service Desk", "retry-extraction")
                    or record.get("extraction") is not None
                    or not isinstance(error, dict)
                    or any(not isinstance(error.get(key), str) or not error[key].strip() for key in ("category", "message", "retry_command"))
                ):
                    raise StateError("Failure completion requires a null extraction and an actionable error route.")
            elif route not in _ROUTES or not isinstance(record.get("extraction"), dict) or record.get("error") is not None:
                raise StateError("Successful completion requires a validated extraction and a human review route.")
            source = record.get("response_source")
            if not isinstance(source, str) or not source:
                raise StateError("Completion must identify its response source.")
            extraction_json = _json(record["extraction"]) if record.get("extraction") is not None else None
            error_json = _json(record["error"]) if record.get("error") is not None else None
            self._db.execute(
                "UPDATE attempts SET state = ?, status = ?, owner = ?, next_action = ?, response_source = ?, "
                "extraction_json = ?, error_json = ?, finished_at = ? WHERE attempt_id = ?",
                ("failed" if failure else "succeeded", *route, source, extraction_json, error_json, _now(), attempt_id),
            )

    def retry(self, document_id: str) -> ScheduledAttempt:
        with self._write():
            current = self.current(document_id)
            if current["state"] in ("pending", "running"):
                raise StateError("Document already has unfinished work; resume it instead of retrying.")
            prepared = _prepare_settings(current["settings"])
            return self._new_attempt(document_id, current["revision_id"], prepared)

    def refresh(self, settings: dict[str, Any], document_id: str | None = None) -> list[ScheduledAttempt]:
        prepared = _prepare_settings(settings)
        with self._write():
            query = (
                "SELECT d.document_id, d.current_attempt_id, r.source_bytes FROM documents d "
                "JOIN revisions r ON r.revision_id = d.current_revision_id"
            )
            if document_id is not None:
                rows = self._db.execute(query + " WHERE d.document_id = ?", (document_id,)).fetchall()
                if not rows:
                    raise StateError("No stored document exists to refresh.")
            else:
                rows = self._db.execute(query + " ORDER BY d.document_id").fetchall()
            jobs = []
            for row in rows:
                job = self._enqueue(row["document_id"], bytes(row["source_bytes"]), prepared)
                if job.attempt_id != row["current_attempt_id"]:
                    jobs.append(job)
            return jobs

"""Operator commands for intake, inspection and restart recovery."""

import argparse
import json
import math
from pathlib import Path
import sqlite3
import sys
from urllib.parse import urlsplit

from .providers import ProviderConfig, ProviderError
from .runner import BusyError, WriterLock, capture_settings, run_jobs
from .state import StateError, StateStore


def _parser():
    parser = argparse.ArgumentParser(prog="it-access", description="Prepare Northstar access requests for human review.")
    parser.add_argument("--db", type=Path, default=Path("state/intake.sqlite3"))
    subparsers = parser.add_subparsers(dest="command", required=True)
    for name in ("intake", "queue", "show", "resume", "retry", "refresh"):
        command = subparsers.add_parser(name)
        command.add_argument("--db", type=Path, default=argparse.SUPPRESS)
        if name in ("intake", "refresh"):
            command.add_argument("--provider", choices=("mock", "openai"), default="mock")
            command.add_argument("--model", default="gpt-4o-2024-08-06")
            command.add_argument("--endpoint", default="https://api.openai.com/v1")
            command.add_argument("--timeout", type=float, default=60.0)
            command.add_argument("--workers", type=int, choices=(1, 2), default=2)
            command.add_argument("--min-interval", type=float, default=1.0)
            command.add_argument("--mock-dir", type=Path, default=Path("tests/mock_responses"))
        if name == "intake":
            command.add_argument("input_directory", type=Path)
        if name == "refresh":
            command.add_argument("--document")
        if name in ("show", "retry"):
            command.add_argument("document_id")
        if name == "show":
            command.add_argument("--history", action="store_true")
        if name in ("show", "queue"):
            command.add_argument("--json", action="store_true")
        if name == "queue":
            command.add_argument("--status", choices=("review", "needs-information", "error", "pending", "processing"))
    return parser


def _validate_processing(args):
    if not math.isfinite(args.timeout) or args.timeout <= 0:
        raise StateError("Timeout must be a positive finite number.")
    if not math.isfinite(args.min_interval) or args.min_interval < 0:
        raise StateError("Start interval must be a finite nonnegative number.")
    try:
        endpoint = urlsplit(args.endpoint)
        if endpoint.scheme != "https" or not endpoint.netloc or endpoint.username or endpoint.password or endpoint.query or endpoint.fragment:
            raise StateError("Endpoint must be an HTTPS URL without credentials, query values or a fragment.")
        endpoint.port
    except ValueError as error:
        raise StateError("Endpoint is not a valid HTTPS service address.") from error
    if not args.model.strip():
        raise StateError("Model must be a nonempty identifier.")
    return ProviderConfig(provider=args.provider, model=args.model, endpoint=args.endpoint.rstrip("/"), timeout_seconds=args.timeout)


def _show_rows(rows):
    print("document_id\tstatus\towner\tnext_action\tattempt_id\tsource_sha256")
    for row in rows:
        print(f"{row['document_id']}\t{row['status']}\t{row['owner']}\t{row['next_action']}\t{row['attempt_id']}\t{row['source_sha256']}")
        if row["error"] is not None:
            print(row["error"]["message"] + "\n" + row["error"]["retry_command"])


def _read(args):
    with StateStore(args.db, read_only=True) as store, store.snapshot():
        if args.command == "queue":
            rows = [row for row in store.queue() if args.status is None or row["status"] == args.status]
            if args.json:
                print(json.dumps(rows, ensure_ascii=False, indent=2))
            else:
                _show_rows(rows)
        else:
            current = store.current(args.document_id)
            result = {"current": current}
            if args.history:
                result["history"] = store.history(args.document_id)
            if args.json:
                print(json.dumps(result, ensure_ascii=False, indent=2))
            else:
                _show_rows([current])
                if args.history:
                    print("History:")
                    _show_rows(result["history"])
    return 0


def _process(args):
    files = None
    settings = provider = None
    if args.command in ("intake", "refresh"):
        config = _validate_processing(args)
        if args.command == "intake":
            if not args.input_directory.is_dir():
                raise StateError("Input directory does not exist or is not a directory.")
            files = sorted(path for path in args.input_directory.glob("*.json") if path.is_file())
            if not files:
                raise StateError("Input directory contains no top-level JSON exports.")
        settings, provider = capture_settings(config, args.mock_dir, args.workers, args.min_interval)
    database = args.db.resolve()
    if args.command != "intake" and not database.is_file():
        raise StateError("Intake database does not exist; run intake first.")
    with WriterLock(database):
        # Capture all input bytes before dispatch so an interrupted run can
        # resume even if the operator removes or changes the input directory.
        sources = [(path.name, path.read_bytes()) for path in files] if files is not None else []
        with StateStore(database) as store:
            store.recover_running()
            if args.command == "intake":
                jobs = [store.enqueue(document_id, raw, settings) for document_id, raw in sources]
            elif args.command == "refresh":
                jobs = store.refresh(settings, args.document)
            elif args.command == "retry":
                jobs = [store.retry(args.document_id)]
            else:
                jobs = store.resume_jobs()
            providers = {}
            if provider is not None:
                key = (settings["provider"], settings.get("mock_dir"), settings["endpoint"])
                providers[key] = provider
            run_jobs(store, jobs, providers=providers)
            failed = [store.current(job.document_id) for job in jobs if store.current(job.document_id)["status"] == "error"]
            for row in failed:
                print(f"{row['document_id']}: {row['error']['message']}\n{row['error']['retry_command']}")
            print(f"Selected {len(jobs)} request(s); {len(failed)} error(s).", flush=True)
            return 1 if failed else 0


def main(argv=None):
    args = _parser().parse_args(argv)
    try:
        return _read(args) if args.command in ("queue", "show") else _process(args)
    except BusyError as error:
        print(str(error), file=sys.stderr)
        return 3
    except (StateError, ProviderError) as error:
        print(str(error), file=sys.stderr)
        return 2
    except (OSError, sqlite3.Error):
        print("Cannot access intake inputs or database; check paths, permissions and availability.", file=sys.stderr)
        return 2
    except KeyboardInterrupt:
        print("Intake interrupted; use resume to continue recorded unfinished work.", file=sys.stderr)
        return 130

"""One admitted writer, bounded provider calls, and durable per-message results."""

from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
import copy
import fcntl
import hashlib
import json
import math
from pathlib import Path
import shlex
import threading
import time
from typing import Any

from . import extraction
from .providers import MockProvider, ProviderConfig, ProviderError
from .state import ScheduledAttempt, StateError, StateStore


class BusyError(StateError):
    pass


class WriterLock:
    def __init__(self, database: Path):
        self.path = Path(str(Path(database).resolve()) + ".lock")
        self._stream = None

    def __enter__(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._stream = self.path.open("a+b")
        try:
            fcntl.flock(self._stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as error:
            self._stream.close()
            self._stream = None
            raise BusyError("Intake is busy with another operator; retry the command after that process finishes.") from error
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        if self._stream is not None:
            fcntl.flock(self._stream, fcntl.LOCK_UN)
            self._stream.close()
            self._stream = None
        # Keep the inode: removing a shared lock file permits competing locks.


class StartGate:
    def __init__(self, interval: float, *, clock=time.monotonic, sleep=time.sleep):
        if not math.isfinite(interval) or interval < 0:
            raise StateError("Start interval must be a finite nonnegative number.")
        self.interval = interval
        self.clock = clock
        self.sleep = sleep
        self._next = None
        self._lock = threading.Lock()

    def wait(self):
        with self._lock:
            now = self.clock()
            if self._next is not None and now < self._next:
                self.sleep(self._next - now)
                now = self.clock()
            self._next = now + self.interval


def provider_for(settings: dict[str, Any]):
    if settings["provider"] == "mock":
        return MockProvider(Path(settings["mock_dir"]))
    raise StateError("The live provider is not available in this build; use mock mode.")


def capture_settings(config: ProviderConfig, mock_dir: Path, workers: int, interval: float):
    settings = {
        "provider": config.provider,
        "endpoint": config.endpoint,
        "model": config.model,
        "generation": {"temperature": config.temperature, "max_output_tokens": config.max_output_tokens, "store": config.store},
        "system_prompt": extraction.build_messages("")[0]["content"],
        "schema_sha256": hashlib.sha256(extraction.SCHEMA_PATH.read_bytes()).hexdigest(),
        "extraction_schema": json.loads(extraction.SCHEMA_PATH.read_text(encoding="utf-8")),
        "policy_sha256": hashlib.sha256(extraction.POLICY_PATH.read_bytes()).hexdigest(),
        "routing_version": extraction.ROUTING_VERSION,
        "mock_dir": str(mock_dir.resolve()),
        "mock_fixture_hashes": {},
        "timeout_seconds": config.timeout_seconds,
        "workers": workers,
        "min_interval": interval,
    }
    settings["prompt_sha256"] = hashlib.sha256(settings["system_prompt"].encode("utf-8")).hexdigest()
    provider = provider_for(settings)
    if isinstance(provider, MockProvider):
        settings["mock_fixture_hashes"] = provider.fixture_hashes()
    return settings, provider


def _parse_export(raw: bytes) -> str:
    try:
        export = json.loads(
            raw.decode("utf-8"), object_pairs_hook=extraction._unique_object,
            parse_constant=extraction._invalid_constant,
        )
    except (UnicodeError, ValueError, RecursionError) as error:
        raise ProviderError("Input export must be unambiguous UTF-8 JSON with a message string.", "input") from error
    if not isinstance(export, dict) or not isinstance(export.get("message"), str):
        raise ProviderError("Input export is missing a message string; correct the export and retry.", "input")
    return export["message"]


def _failure(document_id, source_hash, response_source, database, category, message, retry_after=None):
    error = {
        "category": category,
        "message": message,
        "retry_command": shlex.join(["it-access", "--db", str(database), "retry", document_id]),
    }
    if retry_after is not None:
        error["retry_after"] = retry_after
    return {
        "document_id": document_id, "source_sha256": source_hash,
        "response_source": response_source, "extraction": None,
        "status": "error", "owner": "IT Service Desk",
        "next_action": "retry-extraction", "error": error,
    }


def _process_one(document_id, raw, settings, provider, gate, database):
    source_hash = hashlib.sha256(raw).hexdigest()
    response_source = "mock" if settings["provider"] == "mock" else settings["provider"] + ":" + settings["model"]
    try:
        message = _parse_export(raw)
        # An old generation prompt can be retained, but a different validation
        # schema or routing build must be explicitly refreshed, not mislabeled.
        if (
            settings["schema_sha256"] != hashlib.sha256(extraction.SCHEMA_PATH.read_bytes()).hexdigest()
            or settings["policy_sha256"] != hashlib.sha256(extraction.POLICY_PATH.read_bytes()).hexdigest()
            or settings["routing_version"] != extraction.ROUTING_VERSION
        ):
            raise ProviderError("Recorded policy/schema differs from this build; refresh the document before retrying.", "validation")
        config = ProviderConfig(
            provider=settings["provider"], model=settings["model"], endpoint=settings["endpoint"],
            timeout_seconds=settings["timeout_seconds"], **settings["generation"],
        )
        gate.wait()
        response = provider.extract(document_id=document_id, source_sha256=source_hash, message=message, config=config)
        record = extraction.process_response(document_id=document_id, source_sha256=source_hash, message=message, response=response)
        if record["error"] is not None:
            record["error"]["retry_command"] = shlex.join(["it-access", "--db", str(database), "retry", document_id])
        return record
    except ProviderError as error:
        return _failure(document_id, source_hash, response_source, database, error.category, str(error), error.retry_after)
    except Exception:
        # Never place arbitrary transport/model exceptions into operational logs.
        return _failure(document_id, source_hash, response_source, database, "provider_unavailable", "Extraction could not complete; inspect configuration and retry this message.")


def run_jobs(store: StateStore, jobs: list[ScheduledAttempt], *, providers=None):
    selected = [job for job in jobs if job.needs_processing]
    if not selected:
        return
    recorded = {job.attempt_id: store.attempt(job.attempt_id)["settings"] for job in selected}
    # Conservative limits when resume combines jobs from different old batches.
    workers = min(int(settings.get("workers", 2)) for settings in recorded.values())
    if workers not in (1, 2):
        raise StateError("Recorded worker limit must be 1 or 2.")
    interval = max(float(settings.get("min_interval", 1.0)) for settings in recorded.values())
    gate = StartGate(interval)
    providers = dict(providers or {})
    remaining = iter(selected)
    active = {}

    def submit(pool, job):
        settings = copy.deepcopy(recorded[job.attempt_id])
        key = (settings["provider"], settings.get("mock_dir"), settings["endpoint"])
        if key not in providers:
            providers[key] = provider_for(settings)
        provider = providers[key]
        if isinstance(provider, MockProvider):
            settings["mock_fixture_hashes"] = provider.fixture_hashes()
        settings.update(workers=workers, min_interval=interval)
        store.configure_attempt(job.attempt_id, settings)
        raw = store.source_bytes(job.attempt_id)
        store.mark_running(job.attempt_id)
        future = pool.submit(_process_one, job.document_id, raw, settings, provider, gate, store.path)
        active[future] = job

    with ThreadPoolExecutor(max_workers=workers) as pool:
        for _ in range(workers):
            job = next(remaining, None)
            if job is not None:
                submit(pool, job)
        while active:
            done, _ = wait(active, return_when=FIRST_COMPLETED)
            for future in done:
                job = active.pop(future)
                result = future.result()
                store.finish(job.attempt_id, result)
                print(f"{job.document_id}\t{result['status']}\t{result['owner']}\t{result['next_action']}", flush=True)
                if result["error"] is not None:
                    print(result["error"]["message"] + "\n" + result["error"]["retry_command"], flush=True)
            for _ in range(workers - len(active)):
                job = next(remaining, None)
                if job is not None:
                    submit(pool, job)

